window.__finlexDocLoaded(10175,{"id":10175,"articles":[{"id":1000731,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Governs audits of non-issuers (private companies, nonprofits, and certain employee benefit plans) in the United States, structured via AU-C section numbers largely converged with IAASB ISAs (including SQMS 1–2 and SAS 145–149).","seq":0},{"id":1000732,"no":"AU-C 200–940","heading":"Clarity Convergence with ISAs & Private Company Scope","text":"• Scope Split in the US: SEC public issuers & broker-dealers MUST be audited under PCAOB Standards (AS 1000–6100); private companies and non-issuers are audited under AICPA US GAAS (AU-C sections).\n• High Convergence with ISAs: AU-C numbering mirrors ISA numbering (e.g., AU-C 315 ≈ ISA 315, AU-C 540 ≈ ISA 540, SQMS 1 ≈ ISQM 1, SAS 149 Group Audits ≈ ISA 600 Revised).\n• Key Audit Matters (AU-C 701): Optional for non-issuers (communicated only when engaged to do so).","seq":1},{"id":1000733,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Dual US Audit Regime: Unlike most countries with one unified ISA-based framework, US practice splits between PCAOB (public issuers) and AICPA AU-C (private entities).","seq":2},{"id":1000734,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (AICPA Professional Standards): https://www.aicpa-cima.com/\nStatus: in_force.","seq":3}]});
